-- ES/DE/FR translations for all 3 Croatia milestones.
-- hr-b2b, hr-nonvat reuse the tracker's own existing translations
-- (i18n/{lang}-data.json) verbatim, per tracker-phrasing-wins.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-b2g-2019', 'es', 'La facturación electrónica B2G ya es obligatoria', 'La facturación al sector público lleva años funcionando con facturación electrónica estructurada — Fiskalizacija 2.0 extiende esa misma alineación con EN 16931 a la economía B2B y B2C nacional, mucho más amplia.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-b2g-2019', 'de', 'B2G-E-Rechnung ist bereits verpflichtend', 'Die Rechnungsstellung im öffentlichen Sektor läuft seit Jahren auf strukturierter E-Rechnung — Fiskalizacija 2.0 weitet dieselbe zugrunde liegende EN-16931-Ausrichtung auf die deutlich größere inländische B2B- und B2C-Wirtschaft aus.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-b2g-2019', 'fr', 'La facturation électronique B2G est déjà obligatoire', 'La facturation au secteur public fonctionne depuis des années sur la base de la facturation électronique structurée — Fiskalizacija 2.0 étend le même alignement sur l''EN 16931 à l''économie B2B et B2C nationale, bien plus vaste.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-b2b', 'es', 'Fiskalizacija 2.0 — facturación y reporte electrónico obligatorios para empresas registradas a efectos del IVA', 'La reforma "Fiscalización 2.0" de Croacia hizo obligatoria la facturación electrónica estructurada (emisión y recepción) y el e-reporting en tiempo real para todos los contribuyentes croatas registrados a efectos del IVA, sumándose al mandato de facturación electrónica B2G ya vigente desde 2019.', '["Registre una dirección AMS y contrate un intermediario de información o punto de acceso certificado", "Asegúrese de que los sistemas ERP generen XML UBL 2.1 válido alineado con el CIUS HR-FISK 2.0 (incluidos códigos KPD de 6 dígitos y OIB)", "Incorpore el flujo de trabajo de fiscalización del comprador a 5 días y el e-reporting mensual antes del día 20", "Archive las facturas XML originales durante 11 años"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-b2b', 'de', 'Fiskalizacija 2.0 — verpflichtendes E-Invoicing und E-Reporting für umsatzsteuerpflichtige Unternehmen', 'Kroatiens "Fiskalisierung 2.0"-Reform machte strukturiertes E-Invoicing (Ausstellung und Empfang) sowie Echtzeit-E-Reporting für alle umsatzsteuerpflichtigen, in Kroatien ansässigen Steuerzahler verpflichtend, zusätzlich zur seit 2019 geltenden B2G-E-Invoicing-Pflicht.', '["Registrieren Sie eine AMS-Adresse und beauftragen Sie einen zertifizierten Informationsvermittler oder Access Point", "Stellen Sie sicher, dass ERP-Systeme gültiges UBL-2.1-XML gemäß dem CIUS HR-FISK 2.0 erzeugen (einschließlich 6-stelliger KPD-Codes und OIBs)", "Integrieren Sie den 5-Tage-Fiskalisierungsprozess auf Käuferseite sowie das monatliche E-Reporting bis zum 20.", "Archivieren Sie originale XML-Rechnungen 11 Jahre lang"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-b2b', 'fr', 'Fiskalizacija 2.0 — facturation et déclaration électroniques obligatoires pour les entreprises assujetties à la TVA', 'La réforme croate de « Fiscalisation 2.0 » a rendu obligatoires la facturation électronique structurée (émission et réception) et la déclaration électronique en temps réel pour tous les contribuables croates assujettis à la TVA, en plus de l''obligation de facturation électronique B2G déjà en vigueur depuis 2019.', '["Enregistrez une adresse AMS et contractez un intermédiaire d''information ou un point d''accès certifié", "Assurez-vous que les systèmes ERP produisent du XML UBL 2.1 valide conforme au CIUS HR-FISK 2.0 (y compris les codes KPD à 6 chiffres et les OIB)", "Intégrez le processus de fiscalisation à 5 jours côté acheteur et la déclaration électronique mensuelle avant le 20", "Archivez les factures XML originales pendant 11 ans"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-nonvat', 'es', 'El mandato se extiende a entidades no registradas a efectos del IVA y organismos públicos', 'La obligación de emitir (no solo recibir) facturas electrónicas estructuradas y datos de e-reporting se extiende a entidades no registradas a efectos del IVA — pequeñas empresas, autónomos y ciertos organismos públicos/presupuestarios.', '["Empresas y autónomos no registrados a efectos del IVA: confirmen la capacidad de emisión de facturación electrónica con suficiente antelación a esta fecha", "Los organismos públicos no registrados a efectos del IVA deben completar la integración del punto de acceso durante 2026"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-nonvat', 'de', 'Die Pflicht erweitert sich auf nicht umsatzsteuerregistrierte Einrichtungen und öffentliche Stellen', 'Die Pflicht zur Ausstellung (nicht nur zum Empfang) strukturierter E-Rechnungen und E-Reporting-Daten erweitert sich auf nicht umsatzsteuerregistrierte Einrichtungen — kleine Unternehmen, Selbstständige und bestimmte öffentliche/haushaltsgebundene Stellen.', '["Nicht umsatzsteuerregistrierte Unternehmen und Einzelunternehmer: Bestätigen Sie die Fähigkeit zur E-Rechnungsausstellung rechtzeitig vor diesem Datum", "Nicht umsatzsteuerregistrierte öffentliche Stellen sollten die Access-Point-Integration im Jahr 2026 abschließen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hr-nonvat', 'fr', 'L''obligation s''étend aux entités non assujetties à la TVA et aux organismes publics', 'L''obligation d''émettre (pas seulement de recevoir) des factures électroniques structurées et des données de déclaration électronique s''étend aux entités non assujetties à la TVA — petites entreprises, indépendants et certains organismes publics/budgétaires.', '["Entreprises et indépendants non assujettis à la TVA : vérifiez la capacité d''émission de factures électroniques bien avant cette date", "Les organismes publics non assujettis à la TVA devraient achever l''intégration au point d''accès durant 2026"]');
